/* End-to-end check of the startup path (tests/s10): the demo units rewritten by dyninit_rewrite.py, the
 * table generated by mkxctab.py, run by startup/guest; the destructors they register run through the libc
 * atexit list at exit(), newest first. Built for the host (test_tools.py) and as an ILP32
 * guest under Unicorn (guest/build.sh, same source). */
#include "fnvnx_xc.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#ifdef __ILP32__
#define WHO "guest"
#else
#define WHO "e2e"
#endif

static char g_log[1024];
static int g_fails;

void demo_log(const char *what, int v) {
    char b[32];
    snprintf(b, sizeof b, "%s:%d ", what, v);
    strncat(g_log, b, sizeof g_log - strlen(g_log) - 1);
}

extern int g_runtime_value;

#define EXPECT(c)                                                                                          \
    do {                                                                                                   \
        if (!(c)) {                                                                                        \
            g_fails++;                                                                                     \
            printf("FAIL %s:%d: %s\n  log: %s\n", __FILE__, __LINE__, #c, g_log);                           \
        }                                                                                                  \
    } while (0)

/* Registered first, so it runs last: the destructors of both initialization runs have run, newest first. */
static void check_at_exit(void) {
    EXPECT(strcmp(g_log, "ctor:2 ctor:1 plain:3 dep:20 ~dep:20 dtor:1 dtor:2 ~dep:20 dtor:2 dtor:1 ") == 0);
    printf("s10 %s: %s (%d failed)\n", WHO, g_fails ? "FAIL" : "PASS", g_fails);
}

int main(int argc, char **argv) {
    (void)argc;
    (void)argv;
    fnvnx_xc_report rep;
    char buf[1024];

    if (atexit(check_at_exit) != 0) return 1;

    /* 1. no exe: original address order. GCC's per-unit .init_array order would be a1 a2 a3 b1 (dep:0). */
    g_log[0] = 0;
    EXPECT(fnvnx_xc_run_initializers(NULL, 0, 0, NULL, &rep) == FNVNX_XC_OK);
    EXPECT(strcmp(g_log, "ctor:1 ctor:2 plain:3 dep:20 ") == 0);
    EXPECT(g_runtime_value == 42);
    EXPECT(rep.mode == FNVNX_XC_MODE_ADDRESS && rep.called == 5 && rep.table_entries == 5);
    fnvnx_xc_format_report(&rep, buf, sizeof buf);
    fputs(buf, stdout);

    /* 2. exe present: the captured __xc slots decide the order; 0x00f40060 has no native (demo_c.cpp was
     *    never compiled), two slots run backwards relative to address order */
    const uint32_t slots[] = { 0, 0x00f40020u, 0x00f40010u, 0x00f40030u, 0x00f40060u, 0x00f40050u, 0x00f40040u, 0 };
    g_log[0] = 0;
    g_runtime_value = 0;
    EXPECT(fnvnx_xc_run_initializers(slots, 8, 0, NULL, &rep) == FNVNX_XC_OK);
    EXPECT(strcmp(g_log, "ctor:2 ctor:1 plain:3 dep:20 ") == 0 && g_runtime_value == 42);
    EXPECT(rep.mode == FNVNX_XC_MODE_IMAGE && rep.image_null == 2 && rep.image_missing == 1);
    EXPECT(rep.missing_sample[0] == 0x00f40060u && rep.inversions == 2 && rep.not_in_image == 0);
    fnvnx_xc_format_report(&rep, buf, sizeof buf);
    fputs(buf, stdout);

    exit(g_fails != 0);
}
